with scored as (select *, last_value(browser) ignore nulls over (order by started_at, id rows between unbounded preceding and current row) as last_known_browser, last_value(country) ignore nulls over (partition by device order by started_at, id rows between unbounded preceding and current row) as last_known_country, row_number() over (partition by customer_id, browser order by started_at, id) as seq_no from sessions) select id, customer_id, device, browser, started_at, country, seq_no from scored order by country desc nulls first, seq_no
